import Foundation
import Testing

@testable import SmartTubeIOSCore

@Suite("Dual subtitles")
struct DualSubtitlesTests {

    // json3 as YouTube serves an auto-generated Japanese track: a window event, word segs,
    // an "aAppend" newline event, a speaker marker.
    static let json3 = """
        {"events":[
          {"tStartMs":0,"dDurationMs":66480,"id":1,"wpWinPosId":1,"wsWinStyleId":1},
          {"tStartMs":880,"dDurationMs":8200,"wWinId":1,"segs":[{"utf8":"愛知県豊田で"},{"utf8":"男性が","tOffsetMs":400}]},
          {"tStartMs":4990,"dDurationMs":4090,"wWinId":1,"aAppend":1,"segs":[{"utf8":"\\n"}]},
          {"tStartMs":5000,"dDurationMs":8519,"wWinId":1,"segs":[{"utf8":">> 熊に襲われました。"}]},
          {"tStartMs":9080,"dDurationMs":7760,"wWinId":1,"segs":[{"utf8":"警察が"}]},
          {"tStartMs":13519,"dDurationMs":7161,"wWinId":1,"segs":[{"utf8":"注意を呼びかけています。"}]}
        ]}
        """

    @Test("json3 parses text events, drops blanks and speaker markers")
    func parsesJson3() {
        let cues = Json3Captions.parse(Data(Self.json3.utf8))
        #expect(cues.map(\.text) == ["愛知県豊田で男性が", "熊に襲われました。", "警察が", "注意を呼びかけています。"])
        #expect(cues[0].startTime == 0.88)
        #expect(abs(cues[0].endTime - 9.08) < 0.0001)
    }

    @Test("lines are joined into sentences that end where the next begins")
    func groupsSentences() {
        let s = CaptionSentences.group(Json3Captions.parse(Data(Self.json3.utf8)))
        #expect(s.map(\.text) == ["愛知県豊田で男性が熊に襲われました。", "警察が注意を呼びかけています。"])
        #expect(s[0].startTime == 0.88)
        #expect(s[0].endTime == 9.08)  // cut at the next sentence's start
    }

    @Test("a long run without a full stop is split at the length limit")
    func splitsLongRuns() {
        let cues = (0..<6).map { CaptionCue(startTime: Double($0), endTime: Double($0) + 1.5, text: "あいうえおかきくけこさしすせそ") }
        let s = CaptionSentences.group(cues, maxChars: 40)
        #expect(s.count == 3)
        #expect(s.allSatisfy { $0.text.count <= 40 })
    }

    @Test("json3 URL swaps fmt=vtt for fmt=json3")
    func json3URL() throws {
        let track = CaptionTrack(
            id: "a.ja", baseURL: URL(string: "https://www.youtube.com/api/timedtext?v=x&lang=ja&fmt=vtt")!,
            name: "Japanese", languageCode: "ja", isAutoGenerated: true)
        let q = URLComponents(url: Json3Captions.url(for: track), resolvingAgainstBaseURL: false)?.queryItems ?? []
        #expect(q.filter { $0.name == "fmt" }.map(\.value) == ["json3"])
        #expect(DualSubtitleOptions.applies(to: track))
    }

    @Test("Google Translate's nested array answer is flattened, keeping newlines")
    func parsesTranslateResponse() {
        let body = #"[[["A man was attacked.\n","男性が襲われました。\n",null,null,10],["Police are warning.","警察が注意。",null,null,10]],null,"ja"]"#
        #expect(GoogleTranslator.parseResponse(Data(body.utf8)) == "A man was attacked.\nPolice are warning.")
    }

    @Test("romaji with long-vowel macrons becomes ordinary hiragana")
    func latinToHiragana() {
        #expect(Furigana.hiragana(fromLatin: "tōkyō") == "とうきょう")
        #expect(Furigana.hiragana(fromLatin: "sensei") == "せんせい")
        #expect(Furigana.hiragana(fromLatin: "gakkō") == "がっこう")
    }

    @Test("okurigana stays outside the reading")
    func okurigana() {
        #expect(
            Furigana.annotate("食べる", reading: "たべる")
                == [FuriganaSegment(text: "食", reading: "た"), FuriganaSegment(text: "べる")])
        #expect(Furigana.annotate("お茶", reading: "おちゃ") == [FuriganaSegment(text: "お"), FuriganaSegment(text: "茶", reading: "ちゃ")])
        #expect(Furigana.annotate("ひらがな", reading: "ひらがな") == [FuriganaSegment(text: "ひらがな")])
    }

    @Test("the system tokenizer gives kanji words a reading and keeps all the text")
    func segmentsSentence() {
        let text = "東京で熊に襲われました。"
        let segs = Furigana.segments(text)
        #expect(segs.map(\.text).joined() == text)
        #expect(segs.contains(FuriganaSegment(text: "東京", reading: "とうきょう")))
        #expect(segs.contains { $0.text == "熊" && $0.reading == "くま" })
    }

    @Test("settings turn into caption options; empty language means no translation line")
    func optionsFromSettings() {
        var s = AppSettings()
        #expect(s.dualSubtitleOptions == DualSubtitleOptions(translationLanguage: "en"))
        s.dualTranslationLanguage = ""
        #expect(s.dualSubtitleOptions == DualSubtitleOptions(translationLanguage: nil))
        s.dualSubtitlesEnabled = false
        #expect(s.dualSubtitleOptions == nil)
    }
}
